CREATE FUNCTION ultrabrain.invalidate_fact_evidence_page() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $f$
BEGIN
 IF TG_OP='UPDATE' AND NEW.compiled_truth IS NOT DISTINCT FROM OLD.compiled_truth
  AND NEW.timeline IS NOT DISTINCT FROM OLD.timeline AND NEW.title IS NOT DISTINCT FROM OLD.title
  AND NEW.frontmatter IS NOT DISTINCT FROM OLD.frontmatter AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash
  AND NEW.deleted_at IS NOT DISTINCT FROM OLD.deleted_at AND NEW.slug IS NOT DISTINCT FROM OLD.slug
  AND NEW.source_id IS NOT DISTINCT FROM OLD.source_id THEN RETURN NEW; END IF;
 IF TG_OP!='INSERT' THEN
  UPDATE ultrabrain.fact_evidence SET state='review_required',revision=revision+1,updated_at=now()
   WHERE source_id=OLD.source_id AND evidence_slug=OLD.slug AND state='bound';
 END IF;
 IF TG_OP='INSERT' OR (TG_OP='UPDATE' AND (NEW.source_id IS DISTINCT FROM OLD.source_id OR NEW.slug IS DISTINCT FROM OLD.slug)) THEN
  UPDATE ultrabrain.fact_evidence SET state='review_required',revision=revision+1,updated_at=now()
   WHERE source_id=NEW.source_id AND evidence_slug=NEW.slug AND state='bound';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $f$
